#!/bin/sh
# Builds the Mosquitto config from environment variables each time the
# container starts, so changing MQTT_USER / MQTT_PASS in .env and running
# `docker compose up -d` is all it takes to change the broker login.
set -e

CONF=/mosquitto/config/mosquitto.conf
PASSWD=/mosquitto/config/passwd
mkdir -p /mosquitto/config /mosquitto/data

cat > "$CONF" <<EOF
# Generated by start-mosquitto.sh - edit .env instead of this file
listener 1883
persistence true
persistence_location /mosquitto/data/
log_dest stdout
log_type error
log_type warning
log_type notice
EOF

if [ -n "$MQTT_USER" ]; then
    rm -f "$PASSWD"
    mosquitto_passwd -b -c "$PASSWD" "$MQTT_USER" "$MQTT_PASS"
    chown mosquitto:mosquitto "$PASSWD"
    chmod 0700 "$PASSWD"
    printf 'allow_anonymous false\npassword_file %s\n' "$PASSWD" >> "$CONF"
    echo "Mosquitto: login required (user '$MQTT_USER')"
else
    echo "allow_anonymous true" >> "$CONF"
    echo "Mosquitto: anonymous access allowed (no MQTT_USER set)"
fi

exec mosquitto -c "$CONF"
